import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const a="/assets/befehl-zum-geraet.CqWJEMXm.svg",g=JSON.parse('{"title":"Befehle und Skripte wirken nicht","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/02.befehle-wirken-nicht.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","filePath":"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","lastUpdated":null}'),s={name:"de/adapter/wled/fehlerbehebung/befehle-wirken-nicht.md"};function d(o,e,l,h,c,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="befehle-und-skripte-wirken-nicht" tabindex="-1">Befehle und Skripte wirken nicht <a class="header-anchor" href="#befehle-und-skripte-wirken-nicht" aria-label="Permalink to &quot;Befehle und Skripte wirken nicht&quot;">​</a></h1><p><a id="off-state-not-updated"></a></p><h2 id="warum-wird-der-ein-aus-datenpunkt-nicht-aktualisiert" tabindex="-1">Warum wird der Ein/Aus-Datenpunkt nicht aktualisiert? <a class="header-anchor" href="#warum-wird-der-ein-aus-datenpunkt-nicht-aktualisiert" aria-label="Permalink to &quot;Warum wird der Ein/Aus-Datenpunkt nicht aktualisiert?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="script-not-ps-wled-ignores"></a></p><h2 id="warum-setzt-mein-skript-ps-oder-on-nicht-oder-wled-ignoriert-die-befehle" tabindex="-1">Warum setzt mein Skript ps oder on nicht, oder WLED ignoriert die Befehle? <a class="header-anchor" href="#warum-setzt-mein-skript-ps-oder-on-nicht-oder-wled-ignoriert-die-befehle" aria-label="Permalink to &quot;Warum setzt mein Skript ps oder on nicht, oder WLED ignoriert die Befehle?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist liegt es an einer von fünf Ursachen: Der Wert wurde als Bestätigung (<code>ack=true</code>) statt als Steuerbefehl geschrieben, das Gerät war für den Adapter gerade offline, dasselbe Preset war schon aktiv, der Datentyp stimmt nicht, oder es kamen zu viele Befehle zu schnell hintereinander. Die Checkliste unten führt dich der Reihe nach durch.</p><p>So kommt ein Befehl beim Gerät an: Der Adapter reagiert nur auf Schreibzugriffe mit <code>ack=false</code>. Er baut daraus einen JSON-Befehl, zum Beispiel <code>{&quot;ps&quot;:3}</code> oder <code>{&quot;on&quot;:true}</code>, und schickt ihn sofort ab: über die WebSocket-Verbindung, wenn sie steht, sonst per HTTP an <code>http://192.168.x.y/json</code>. Es gibt keine Warteschlange und keine Wiederholung.</p><p><img src="'+a+'" alt="Ablauf eines Befehls: Nur Werte mit ack=false werden gesendet, nur an ein verbundenes Gerät, per WebSocket oder HTTP. Was nicht ankommt, ist verloren."></p><h3 id="checkliste" tabindex="-1">Checkliste <a class="header-anchor" href="#checkliste" aria-label="Permalink to &quot;Checkliste&quot;">​</a></h3><ol><li><strong>Steuern statt aktualisieren.</strong> In Blockly muss der Block „steuere“ sein, nicht „aktualisiere“. In JavaScript schreibst du <code>setState(id, wert)</code> ohne <code>true</code> als drittes Argument. Ein Wert mit <code>ack=true</code> gilt als Rückmeldung vom Gerät und wird nicht gesendet.</li></ol><ol start="2"><li><strong>Von Hand testen.</strong> Schreib denselben Wert im Objektbaum des Admins in den Datenpunkt. Reagiert WLED darauf, liegt der Fehler im Skript, zum Beispiel an verschachtelten Auslösern oder einer falschen Objekt-ID. Die IDs der Geräte sind ihre MAC-Adressen, sie ändern sich nicht, wenn du das Gerät umbenennst.</li></ol><ol start="3"><li><strong>Ist das Gerät online?</strong> Schau auf <code>wled.0.&lt;MAC&gt;._info._online</code>. Befehle an ein Gerät, das nicht erreichbar ist, gehen verloren. Der Adapter puffert nichts und wiederholt nichts. <ul><li><strong>Bis v0.9.2:</strong> Im Log steht ein Fehler „Sending command to WLED device … failed with error …“. Ist das Gerät dem Adapter gerade gar nicht bekannt, steht dort stattdessen ein TypeError, der auch an Sentry gemeldet wird.</li><li><strong>Ab v0.9.3:</strong> Der Adapter verwirft den Befehl mit der Warnung <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for … discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ul></li></ol><ol start="4"><li><strong>Zu schnell nach dem Einschalten?</strong> Bekommt WLED gerade erst Strom, zum Beispiel über eine Zwischensteckdose, ist es erst nach einigen Sekunden im WLAN erreichbar. Befehle davor gehen verloren. <ul><li><strong>Ab v0.9.3</strong> kommt hinzu: Der Adapter sendet nur an Geräte, die er als verbunden kennt (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). Dass ein Gerät wieder da ist, merkt er erst bei der nächsten Prüfung. Die läuft standardmäßig alle 30 Sekunden („Intervall in Sekunden“). War das Gerät länger aus, prüft er seltener: Die Abstände verdoppeln sich bis höchstens 10 Minuten, und nach 5 Fehlversuchen („Maximale Wiederholungsversuche“) nur noch einmal pro Stunde. Bis dahin verwirft er Befehle.</li><li>Lass dein Skript deshalb warten, bis <code>wled.0.&lt;MAC&gt;._info._online</code> auf <code>true</code> geht, und schick den Befehl erst dann.</li></ul></li></ol><ol start="5"><li><strong>Dasselbe Preset schon aktiv?</strong> Zeigt <code>ps</code> bereits die Nummer, die du schreibst, lädt WLED das Preset nicht noch einmal. Das passiert auch, wenn du das Licht zwischendurch über <code>on</code> ausgeschaltet hast. Schick dann <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> an <code>wled.0.&lt;MAC&gt;.action</code>.</li></ol><ol start="6"><li><strong>Passt der Datentyp?</strong> <code>on</code> erwartet <code>true</code> oder <code>false</code>, <code>ps</code> eine Zahl. Schreibst du <code>on</code> als Text, macht WLED etwas anderes als gedacht: Ein Text, der mit <code>t</code> beginnt (also auch <code>&quot;true&quot;</code>), schaltet um, und <code>&quot;false&quot;</code> als Text bewirkt gar nichts. ioBroker meldet einen falschen Datentyp zusätzlich als Warnung im Log.</li></ol><ol start="7"><li><strong>Zu viele Befehle hintereinander?</strong> Jeder geänderte Datenpunkt ist ein eigener Befehl. Schreibt dein Skript <code>on</code>, <code>bri</code>, Farbe und <code>ps</code> direkt nacheinander, kann WLED Befehle verlieren oder mit Zeitüberschreitung antworten. Fass zusammengehörende Werte in einem JSON-Befehl über <code>action</code> zusammen, zum Beispiel <code>{&quot;on&quot;:true,&quot;bri&quot;:128,&quot;ps&quot;:3}</code>, oder leg sie gleich in einem Preset ab und setz nur <code>ps</code>. Wenn es einzelne Befehle sein müssen, lass zwischen ihnen eine kurze Pause.</li></ol><ol start="8"><li><strong>Rückmeldung über WebSocket.</strong> Läuft die Verbindung über WebSocket, setzt der Adapter <strong>bis v0.9.2</strong> selbst kein <code>ack=true</code> und meldet auch keinen Sendefehler. Das <code>ack</code> kommt erst, wenn WLED seinen neuen Zustand meldet. Bleibt ein Wert auf <code>ack=false</code>, ist der Befehl wahrscheinlich nicht angekommen. <strong>Ab v0.9.3:</strong> Der Adapter setzt <code>ack=true</code>, sobald der Befehl gesendet ist, und schreibt eine Warnung „Sending command for … failed“ ins Log, wenn das Senden scheitert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ol><ol start="9"><li><strong>Segment-Befehle.</strong> Setzt du einen Wert in einem Segment, etwa <code>wled.0.&lt;MAC&gt;.seg.0.fx</code>, geht der Befehl nur an dieses Segment. Prüf, ob du das richtige Segment erwischt hast und ob es eingeschaltet ist.</li></ol><ol start="10"><li><strong>Debug-Log ansehen.</strong> Stell die Instanz auf Log-Stufe „debug“. Bei jedem Befehl erscheint dann „Sending state change by websocket …“ oder „Sending state change by http-API …“ mit dem gesendeten JSON. Fehlt die Zeile, ist der Befehl gar nicht beim Adapter angekommen.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Liest dein Skript <code>on</code>, beachte: <strong>Bis v0.9.2</strong> setzt der Adapter <code>on</code> auf <code>false</code> und <code>bri</code> auf <code>0</code>, wenn ein Gerät offline geht, und beim Adapterstart. <strong>Ab v0.9.3:</strong> Beide behalten ihren letzten Wert, die echten Werte kommen beim Wiederverbinden vom Gerät (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Presets per Datenpunkt ps schalten</a> · <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a> · <a href="#several-commands-quick-succession-lead">Mehrere Befehle führen zu ETIMEDOUT</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät online ist</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wiederholungen bei Offline-Geräten</a> · <a href="./../referenz/log-meldungen#warnings-about-wrong-data-type">Warnungen zum falschen Datentyp</a></p><p><a id="several-commands-quick-succession-lead"></a></p><h2 id="warum-fuhren-mehrere-befehle-kurz-hintereinander-zu-etimedout" tabindex="-1">Warum führen mehrere Befehle kurz hintereinander zu ETIMEDOUT? <a class="header-anchor" href="#warum-fuhren-mehrere-befehle-kurz-hintereinander-zu-etimedout" aria-label="Permalink to &quot;Warum führen mehrere Befehle kurz hintereinander zu ETIMEDOUT?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="ps-jump-1-not-show"></a></p><h2 id="warum-springt-ps-auf-1-oder-zeigt-nicht-das-gewahlte-preset" tabindex="-1">Warum springt ps auf -1 oder zeigt nicht das gewählte Preset? <a class="header-anchor" href="#warum-springt-ps-auf-1-oder-zeigt-nicht-das-gewahlte-preset" aria-label="Permalink to &quot;Warum springt ps auf -1 oder zeigt nicht das gewählte Preset?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="some-leds-stay-after-switching"></a></p><h2 id="warum-bleiben-nach-dem-ausschalten-einige-leds-an" tabindex="-1">Warum bleiben nach dem Ausschalten einige LEDs an? <a class="header-anchor" href="#warum-bleiben-nach-dem-ausschalten-einige-leds-an" aria-label="Permalink to &quot;Warum bleiben nach dem Ausschalten einige LEDs an?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="cct-state-have-no-effect"></a></p><h2 id="warum-hat-der-datenpunkt-cct-keine-wirkung" tabindex="-1">Warum hat der Datenpunkt cct keine Wirkung? <a class="header-anchor" href="#warum-hat-der-datenpunkt-cct-keine-wirkung" aria-label="Permalink to &quot;Warum hat der Datenpunkt cct keine Wirkung?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',34)])])}const f=t(s,[["render",d]]);export{g as __pageData,f as default};
